 $profiles+=[ordered]@{factoryMode=$mode;replacementUnits=[int[]]$templates[$template];advertisedMaximum=$maximum;retainsEncoder=[object]::ReferenceEquals($encoder,$encoding.EncoderFallback);retainsDecoder=[object]::ReferenceEquals($decoder,$encoding.DecoderFallback);rows=$rows;capacities=$capacities}
}}
